require __DIR__.'/_layout.php';$u=require_admin();if(!is_general_admin($u)){http_response_code(403);exit('Somente o Admin Geral pode emitir diplomas e certificados.');}$pdo=db();$err='';$year=(int)($_GET['year']??$_POST['year']??date('Y'));if($year<2000||$year>2100)$year=(int)date('Y');
if($_SERVER['REQUEST_METHOD']==='POST'){csrf_check();try{$action=(string)($_POST['action']??'issue');if($action==='issue'){$personType=(string)($_POST['person_type']??'');$personId=(int)($_POST['person_id']??0);$docType=(string)($_POST['document_type']??'');$notes=trim((string)($_POST['notes']??''));$docId=recognition_issue($personType,$personId,$docType,$year,(int)$u['id'],$notes);go('reconhecimentos.php?year='.$year,'Documento emitido/reativado.');}if($action==='cancel'){$id=(int)($_POST['document_id']??0);$pdo->prepare("UPDATE recognition_documents SET status='CANCELADO',updated_at=? WHERE id=?")->execute([now_iso(),$id]);go('reconhecimentos.php?year='.$year,'Documento cancelado.');}}catch(Throwable $e){$err=$e->getMessage();}}
$q=trim((string)($_GET['q']??''));$kind=(string)($_GET['kind']??'TODOS');$allowed=['TODOS','ALUNO','EQUIPE','PARCEIRO','INSTITUCIONAL'];if(!in_array($kind,$allowed,true))$kind='TODOS';$people=[];
if(in_array($kind,['TODOS','ALUNO'],true)){$sql="SELECT id,'ALUNO' person_type,student_name full_name,preferred_name,registration_number reference,instrument role_name,created_at,status FROM enrollments WHERE deleted_at IS NULL";$params=[];if($q!==''){$sql.=" AND (student_name LIKE ? OR preferred_name LIKE ? OR registration_number LIKE ?)";$like='%'.$q.'%';$params=[$like,$like,$like];}$sql.=" ORDER BY student_name";$st=$pdo->prepare($sql);$st->execute($params);$people=array_merge($people,$st->fetchAll());}
if(in_array($kind,['TODOS','EQUIPE'],true)){$sql="SELECT tm.id,'EQUIPE' person_type,tm.full_name,tm.preferred_name,tm.application_number reference,tr.name role_name,tm.created_at,tm.status FROM team_members tm LEFT JOIN team_roles tr ON tr.id=tm.role_id WHERE tm.deleted_at IS NULL";$params=[];if($q!==''){$sql.=" AND (tm.full_name LIKE ? OR tm.preferred_name LIKE ? OR tm.application_number LIKE ?)";$like='%'.$q.'%';$params=[$like,$like,$like];}$sql.=" ORDER BY tm.full_name";$st=$pdo->prepare($sql);$st->execute($params);$people=array_merge($people,$st->fetchAll());}
if(in_array($kind,['TODOS','PARCEIRO'],true)){$sql="SELECT id,'PARCEIRO' person_type,name full_name,'' preferred_name,category reference,category role_name,created_at,CASE active WHEN 1 THEN 'ATIVO' ELSE 'OCULTO' END status FROM sponsors";$params=[];if($q!==''){$sql.=" WHERE (name LIKE ? OR category LIKE ?)";$like='%'.$q.'%';$params=[$like,$like];}$sql.=" ORDER BY name";$st=$pdo->prepare($sql);$st->execute($params);$people=array_merge($people,$st->fetchAll());}
if(in_array($kind,['TODOS','INSTITUCIONAL'],true)){$sql="SELECT id,'INSTITUCIONAL' person_type,name full_name,'' preferred_name,category reference,category role_name,created_at,CASE active WHEN 1 THEN 'ATIVO' ELSE 'OCULTO' END status FROM institutional_supporters";$params=[];if($q!==''){$sql.=" WHERE (name LIKE ? OR category LIKE ?)";$like='%'.$q.'%';$params=[$like,$like];}$sql.=" ORDER BY name";$st=$pdo->prepare($sql);$st->execute($params);$people=array_merge($people,$st->fetchAll());}
usort($people,fn($a,$b)=>strnatcasecmp((string)$a['full_name'],(string)$b['full_name']));admin_header('Diplomas e Certificados Premium');$msg=flash();?>
<?php if($msg):?><div class="alert ok"><?=e($msg)?></div><?php endif;?><?php if($err):?><div class="alert error"><?=e($err)?></div><?php endif;?>
<section class="panel recognition-admin-intro recognition-premium-intro"><div class="panel-heading-flex"><div><span>RECONHECIMENTO ANUAL BAMAB</span><h2>Diplomas, Certificados e Certificados de Parceiros</h2><p>Aluno e equipe podem receber <strong>Certificado, Diploma ou os dois</strong>, conforme decisão do Admin. Parceiros, patrocinadores, apoiadores, Prefeitura e Secretarias recebem Certificado de Parceria/Reconhecimento. Os documentos de alunos incluem no verso o histórico das notas do ano.</p></div><div class="recognition-head-actions"><a class="small-button" href="reconhecimento_config.php">EDITAR MODELOS E ASSINATURAS</a></div></div></section>
<form class="panel recognition-filter" method="get"><div class="grid4"><label>Ano<input type="number" name="year" min="2000" max="2100" value="<?=$year?>"></label><label>Grupo<select name="kind"><option value="TODOS" <?=$kind==='TODOS'?'selected':''?>>TODOS</option><option value="ALUNO" <?=$kind==='ALUNO'?'selected':''?>>ALUNOS</option><option value="EQUIPE" <?=$kind==='EQUIPE'?'selected':''?>>EQUIPE</option><option value="PARCEIRO" <?=$kind==='PARCEIRO'?'selected':''?>>PATROCINADORES / PARCEIROS</option><option value="INSTITUCIONAL" <?=$kind==='INSTITUCIONAL'?'selected':''?>>PREFEITURA / SECRETARIAS</option></select></label><label>Buscar<input name="q" value="<?=e($q)?>" placeholder="Nome, matrícula, categoria"></label><button class="primary">FILTRAR</button></div></form>
<section class="panel"><div class="panel-heading-flex"><div><h2>Emissão — <?=$year?></h2><p><?=count($people)?> registro(s) disponível(is). Foto 3x4 não é necessária.</p></div></div><div class="recognition-list"><?php if(!$people):?><p>Nenhum registro encontrado.</p><?php endif;?><?php foreach($people as $p):$ptype=(string)$p['person_type'];$docs=recognition_documents_for_person($ptype,(int)$p['id'],$year);$by=[];foreach($docs as $d)$by[$d['document_type']]=$d;$types=recognition_document_types_for_person($ptype);?><article class="recognition-person-card"><div class="recognition-person-main"><span><?=e(recognition_person_types()[$ptype]??$ptype)?> · <?=e((string)$p['reference'])?></span><h3><?=e(recognition_display_name($p))?></h3><p><?=e((string)($p['role_name']?:'BAMAB'))?></p><strong><?=e(recognition_suggestion($p,$year,$ptype))?></strong><?php if($ptype==='ALUNO'): $historyCount=recognition_student_history_count((int)$p['id'],$year);?><small class="recognition-history-count"><?=$historyCount?> avaliação(ões) final(is) no histórico de <?=$year?></small><?php endif;?></div><div class="recognition-doc-actions <?=count($types)===1?'single-doc':''?>"><?php foreach($types as $type=>$label):$d=$by[$type]??null;?><div class="recognition-doc-box"><b><?=e($ptype==='PARCEIRO'||$ptype==='INSTITUCIONAL'?'CERTIFICADO DE PARCERIA / RECONHECIMENTO':mb_strtoupper($label))?></b><?php if($d&&$d['status']==='ATIVO'):?><span class="doc-issued">EMITIDO · <?=e($d['serial_number'])?></span><a class="small-button card-print-btn" target="_blank" rel="noopener noreferrer" href="reconhecimento_documento.php?id=<?=(int)$d['id']?>">ABRIR / IMPRIMIR</a><form method="post" onsubmit="return confirm('Cancelar este documento?')"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="year" value="<?=$year?>"><input type="hidden" name="action" value="cancel"><input type="hidden" name="document_id" value="<?=(int)$d['id']?>"><button class="danger-soft">CANCELAR</button></form><?php else:?><form method="post"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="year" value="<?=$year?>"><input type="hidden" name="action" value="issue"><input type="hidden" name="person_type" value="<?=e($ptype)?>"><input type="hidden" name="person_id" value="<?=(int)$p['id']?>"><input type="hidden" name="document_type" value="<?=e($type)?>"><button class="primary">EMITIR <?=e($ptype==='PARCEIRO'||$ptype==='INSTITUCIONAL'?'CERTIFICADO':mb_strtoupper($label))?></button></form><?php endif;?></div><?php endforeach;?></div></article><?php endforeach;?></div></section>
<?php admin_footer();?>
